"use client";
import { scrollAreaListChildren } from "@/components/ui/scroll-area";

import * as React from "react";
import { useMorph } from "@/lib/cojeev-motion/use-morph";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import * as Primitive from "@radix-ui/react-dropdown-menu";
import {
  useFlowAppearance,
  useFlowGroup,
} from "@/lib/cojeev-motion/use-flow";

import { adornItem, adornMenuItem, itemText, type ItemAdornmentItemProps } from "@/components/ui/item-adornment";
import { StateChevron, AnimatedIcon } from "@/components/ui/animated-icon";

export type DropdownMenuProps = React.ComponentProps<typeof Primitive.Root>;
export function DropdownMenu(props: DropdownMenuProps) {
  return <Primitive.Root {...props} />;
}
export type DropdownMenuPortalProps = React.ComponentProps<
  typeof Primitive.Portal
>;
export function DropdownMenuPortal(props: DropdownMenuPortalProps) {
  return <Primitive.Portal {...props} />;
}
export type DropdownMenuGroupProps = React.ComponentProps<
  typeof Primitive.Group
>;
export function DropdownMenuGroup(props: DropdownMenuGroupProps) {
  return <Primitive.Group data-slot="dropdown-menu-group" {...props} />;
}
export type DropdownMenuRadioGroupProps = React.ComponentProps<
  typeof Primitive.RadioGroup
>;
export function DropdownMenuRadioGroup(props: DropdownMenuRadioGroupProps) {
  return (
    <Primitive.RadioGroup data-slot="dropdown-menu-radiogroup" {...props} />
  );
}
export type DropdownMenuSubProps = React.ComponentProps<typeof Primitive.Sub>;
export function DropdownMenuSub(props: DropdownMenuSubProps) {
  return <Primitive.Sub {...props} />;
}
export type DropdownMenuTriggerProps = React.ComponentProps<
  typeof Primitive.Trigger
> & { chevron?: boolean };
export function DropdownMenuTrigger({
  className,
  children,
  chevron = false,
  ref,
  ...props
}: DropdownMenuTriggerProps) {
  return (
    <Primitive.Trigger
      ref={ref}
      data-slot="dropdown-menu-trigger"
      data-part="trigger"
      data-menu=""
      className={cn("", className)}
      {...props}
    >{adornItem(children, false, "", props.asChild, chevron ? <StateChevron /> : null)}</Primitive.Trigger>
  );
}
export const dropdownmenuContentVariants = cva(
  "v-menu [background:var(--popover)] [border-radius:var(--r-card-sm)] [padding:var(--s-2)] [min-width:200px] [box-shadow:var(--shadow-float)] [border:1px_solid_var(--v-border)] [display:grid] [gap:2px]",
);
export type DropdownMenuContentProps = React.ComponentProps<
  typeof Primitive.Content
>;
export function DropdownMenuContent({
  className,
  ref,
  children,
  sideOffset = 6,
  ...props
}: DropdownMenuContentProps) {
  const morphRef = useMorph<HTMLDivElement>("surfaces", ref);
  const groupRef = useFlowGroup<HTMLDivElement>(morphRef, {
    itemSelector: ".v-menu__item",
    activeSelector: "[data-highlighted]",
  });
  const flowRef = useFlowAppearance<HTMLDivElement>(true, groupRef, "grow");
  return (
    <Primitive.Portal>
      <Primitive.Content
        ref={flowRef}
        data-slot="dropdown-menu-content"
        data-part="content"
        sideOffset={sideOffset}
        className={cn(dropdownmenuContentVariants(), className)}
        {...props}
      >
        {scrollAreaListChildren(children, props.asChild)}
      </Primitive.Content>
    </Primitive.Portal>
  );
}
export type DropdownMenuSubContentProps = React.ComponentProps<
  typeof Primitive.SubContent
>;
export function DropdownMenuSubContent({
  className,
  children,
  ref,
  ...props
}: DropdownMenuSubContentProps) {
  const morphRef = useMorph<HTMLDivElement>("surfaces", ref);
  const groupRef = useFlowGroup<HTMLDivElement>(morphRef, {
    itemSelector: ".v-menu__item",
    activeSelector: "[data-highlighted]",
  });
  const flowRef = useFlowAppearance<HTMLDivElement>(true, groupRef, "grow");
  return (
    <Primitive.Portal>
      <Primitive.SubContent
        ref={flowRef}
        data-slot="dropdown-menu-sub-content"
        data-part="content"
        className={cn(dropdownmenuContentVariants(), className)}
        {...props}
      >{scrollAreaListChildren(children, props.asChild)}</Primitive.SubContent>
    </Primitive.Portal>
  );
}
export type DropdownMenuItemProps = React.ComponentProps<
  typeof Primitive.Item
> & { variant?: "default" | "danger"; inset?: boolean } & ItemAdornmentItemProps;
export function DropdownMenuItem({
  className,
  children,
  adornment,
  adornmentId,
  variant,
  inset,
  ref,
  ...props
}: DropdownMenuItemProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  return (
    <Primitive.Item
      ref={morphRef}
      data-slot="dropdown-menu-item"
      data-part="item"
      data-inset={inset || undefined}
      className={cn(
        "v-menu__item flex items-center gap-[var(--s-3)] min-h-10 px-[var(--s-3)] rounded-[var(--r-md)] text-[length:var(--fs-control)] w-full text-left whitespace-nowrap outline-none",
        variant === "danger" && "-danger",
        className,
      )}
      {...props}
    >{adornMenuItem(children, adornment, adornmentId ?? props.textValue ?? props.id ?? itemText(children), props.asChild)}</Primitive.Item>
  );
}
export type DropdownMenuSubTriggerProps = React.ComponentProps<
  typeof Primitive.SubTrigger
> & { inset?: boolean } & ItemAdornmentItemProps;
export function DropdownMenuSubTrigger({
  className,
  adornment,
  adornmentId,
  inset,
  children,
  ref,
  ...props
}: DropdownMenuSubTriggerProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  return (
    <Primitive.SubTrigger
      ref={morphRef}
      data-slot="dropdown-menu-sub-trigger"
      data-part="item"
      data-inset={inset || undefined}
      className={cn("v-menu__item", className)}
      {...props}
    >
      {adornMenuItem(children, adornment, adornmentId ?? props.textValue ?? props.id ?? itemText(children), props.asChild, <StateChevron direction="right" />)}
    </Primitive.SubTrigger>
  );
}
export type DropdownMenuCheckboxItemProps = React.ComponentProps<
  typeof Primitive.CheckboxItem
> & ItemAdornmentItemProps;
export function DropdownMenuCheckboxItem({
  className,
  adornment,
  adornmentId,
  children,
  ref,
  ...props
}: DropdownMenuCheckboxItemProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  return (
    <Primitive.CheckboxItem
      ref={morphRef}
      data-slot="dropdown-menu-checkbox-item"
      data-part="item"
      className={cn("v-menu__item", className)}
      {...props}
    >
      {adornMenuItem(children, adornment, adornmentId ?? props.textValue ?? props.id ?? itemText(children), props.asChild, <span className="v-menu__check" aria-hidden="true"><Primitive.ItemIndicator data-slot="dropdown-menu-item-indicator" data-part="indicator"><AnimatedIcon name="check" preset="validation" /></Primitive.ItemIndicator></span>)}
    </Primitive.CheckboxItem>
  );
}
export type DropdownMenuRadioItemProps = React.ComponentProps<
  typeof Primitive.RadioItem
> & ItemAdornmentItemProps;
export function DropdownMenuRadioItem({
  className,
  adornment,
  adornmentId,
  children,
  ref,
  ...props
}: DropdownMenuRadioItemProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  return (
    <Primitive.RadioItem
      ref={morphRef}
      data-slot="dropdown-menu-radio-item"
      data-part="item"
      className={cn("v-menu__item", className)}
      {...props}
    >
      {adornMenuItem(children, adornment, adornmentId ?? props.textValue ?? props.id ?? itemText(children), props.asChild, <span className="v-menu__check" aria-hidden="true"><Primitive.ItemIndicator data-slot="dropdown-menu-item-indicator" data-part="indicator"><AnimatedIcon name="dot" preset="validation" /></Primitive.ItemIndicator></span>)}
    </Primitive.RadioItem>
  );
}
export type DropdownMenuLabelProps = React.ComponentProps<
  typeof Primitive.Label
>;
export function DropdownMenuLabel({
  className,
  ...props
}: DropdownMenuLabelProps) {
  return (
    <Primitive.Label
      data-slot="dropdown-menu-label"
      data-part="group"
      className={cn("v-menu__group", className)}
      {...props}
    />
  );
}
export type DropdownMenuSeparatorProps = React.ComponentProps<
  typeof Primitive.Separator
>;
export function DropdownMenuSeparator({
  className,
  ...props
}: DropdownMenuSeparatorProps) {
  return (
    <Primitive.Separator
      data-slot="dropdown-menu-separator"
      data-part="separator"
      className={cn("v-menu__sep", className)}
      {...props}
    />
  );
}
export type DropdownMenuShortcutProps = React.ComponentProps<"span">;
export function DropdownMenuShortcut({
  className,
  ...props
}: DropdownMenuShortcutProps) {
  return (
    <span
      data-slot="dropdown-menu-shortcut"
      className={cn(
        "ml-auto text-[11px] text-[color:var(--muted-foreground)]",
        className,
      )}
      {...props}
    />
  );
}

@layer cojeev-states {
/* Cojeev authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-menu__item:where(
  [data-slot="dropdown-menu"],
  [data-slot^="dropdown-menu-"]
) {
  display: flex;
  align-items: center;
  gap: var(--s-3);
  min-height: 40px;
  padding: 0 var(--s-3);
  border-radius: var(--r-md);
  font-size: var(--fs-control);
  width: 100%;
  text-align: left;
  white-space: nowrap;
}
.v-menu__item:where(
    [data-slot="dropdown-menu"],
    [data-slot^="dropdown-menu-"]
  ):hover,
.v-menu__item:where(
    [data-slot="dropdown-menu"],
    [data-slot^="dropdown-menu-"]
  )[data-highlighted] {
  background: var(--v-beige);
}
.v-menu__item:where(
    [data-slot="dropdown-menu"],
    [data-slot^="dropdown-menu-"]
  ).-danger {
  color: var(--v-danger-ink);
}
.v-menu__sep:where([data-slot="dropdown-menu"], [data-slot^="dropdown-menu-"]) {
  height: 1px;
  background: var(--v-border);
  margin: 4px 0;
}
.v-menu__group:where(
  [data-slot="dropdown-menu"],
  [data-slot^="dropdown-menu-"]
) {
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted-foreground);
  padding: 8px 12px 4px;
}
.v-menu:where([data-slot="dropdown-menu"], [data-slot^="dropdown-menu-"]) {
  scrollbar-gutter: stable;
}
.v-menu:where(
    [data-slot="dropdown-menu"],
    [data-slot^="dropdown-menu-"]
  )::-webkit-scrollbar {
  width: 12px;
  height: 12px;
}
.v-menu:where(
    [data-slot="dropdown-menu"],
    [data-slot^="dropdown-menu-"]
  )::-webkit-scrollbar-track {
  background: transparent;
  border-radius: 999px;
}
.v-menu:where(
    [data-slot="dropdown-menu"],
    [data-slot^="dropdown-menu-"]
  )::-webkit-scrollbar-thumb {
  background: color-mix(in oklab, var(--v-ink) 34%, transparent);
  border-radius: 999px;
  border: 4px solid transparent;
  background-clip: content-box;
  min-height: 36px;
}
.v-menu:where([data-slot="dropdown-menu"], [data-slot^="dropdown-menu-"]) {
  scrollbar-gutter: stable;
}
.v-menu:where([data-slot="dropdown-menu"], [data-slot^="dropdown-menu-"]) {
  scrollbar-gutter: stable;
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="dropdown-menu"],
  [data-slot^="dropdown-menu-"],
  [data-slot="dropdown-menu"]::before,
  [data-slot="dropdown-menu"]::after,
  [data-slot^="dropdown-menu-"]::before,
  [data-slot^="dropdown-menu-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

[data-slot^="dropdown-menu-"][data-inset] {
  padding-left: 32px;
}
[data-slot^="dropdown-menu-"][data-disabled] {
  color: var(--v-disabled-ink);
  cursor: not-allowed;
}
[data-slot^="dropdown-menu-"][data-highlighted] {
  outline: none;
  background: var(--v-beige);
}

[data-slot="dropdown-menu-content"], [data-slot="dropdown-menu-sub-content"] {
 min-width:min(200px,calc(100vw - 24px)); max-width:calc(100vw - 24px);
 max-height:min(480px,var(--radix-dropdown-menu-content-available-height,calc(100dvh - 32px)));
 overflow:visible; overscroll-behavior:contain; overflow-wrap:anywhere;
}
[data-slot="dropdown-menu-item"] { min-width:0; height:auto; min-height:36px; white-space:normal; }
[data-slot="dropdown-menu-content"], [data-slot="dropdown-menu-sub-content"] { z-index:var(--z-popover); }
[data-slot^="dropdown-menu-"][data-part="item"] { min-width:0; white-space:normal; overflow-wrap:anywhere; padding-block:8px; }

/* Compact by default; --menu-width or inline width can deliberately match a large trigger. */
[data-slot="dropdown-menu-content"], [data-slot="dropdown-menu-sub-content"] { width:var(--menu-width,260px); min-width:min(200px,calc(100vw - 24px)); max-width:calc(100vw - 24px); color:var(--popover-foreground); }
[data-slot^="dropdown-menu-"][data-part="item"] { min-width:0; min-height:44px; padding-block:7px; gap:10px; white-space:normal; overflow-wrap:anywhere; text-align:start; }
[data-slot^="dropdown-menu-"][data-part="item"]:is(:hover,[data-highlighted],[data-state="checked"]) { background:var(--v-beige); color:var(--v-text); }
[data-slot^="dropdown-menu-"][data-part="item"][data-state="checked"] { background:var(--v-pink-soft); }
[data-slot^="dropdown-menu-"][data-part="item"]:active { background:var(--v-pink-soft); color:var(--v-text); }
[data-slot^="dropdown-menu-"][data-part="item"].-danger { color:var(--v-danger-ink); }
[data-slot^="dropdown-menu-"][data-part="item"][data-disabled] { background:transparent; color:var(--v-disabled-ink); }
[data-slot^="dropdown-menu-"] .v-menu__check { display:inline-grid; place-items:center; width:18px; min-width:18px; margin-inline-start:auto; color:inherit; }
[data-slot^="dropdown-menu-"] .v-menu__check .v-icon { width:16px; height:16px; }

/* A native flyout may share a narrow viewport with its parent. Use Popper's
   measured free width so its labels wrap instead of leaving the screen. */
[data-slot="dropdown-menu-sub-content"] { min-width:min(200px,var(--radix-dropdown-menu-content-available-width,200px)); max-width:min(calc(100vw - 24px),var(--radix-dropdown-menu-content-available-width,260px)); }

/* The shared ScrollArea owns menu overflow and its custom thumb. */
:is([data-slot="dropdown-menu-content"],[data-slot="dropdown-menu-sub-content"]) .v-list-scroll { --list-scroll-max-height:min(320px, calc(var(--radix-popper-available-height, 60dvh) - 20px)); }

}
